package com.example.Hospital.Management.System.services; import com.example.Hospital.Management.System.entities.*; import com.example.Hospital.Management.System.dtos.*; import com.example.Hospital.Management.System.repositories.*; import com.example.Hospital.Management.System.exceptions.*; import org.springframework.stereotype.Service; import java.util.*; @Service public class PatientService{private final PatientRepository r;private final HospitalRepository hr;public PatientService(PatientRepository r,HospitalRepository hr){this.r=r;this.hr=hr;} private Patient find(Long id){return r.findById(id).filter(BaseClass::getIsActive).orElseThrow(()->new ResourceNotFoundException("Patient not found"));} private PatientDTO dto(Patient e){return PatientDTO.builder().id(e.getId()).name(e.getName()).gender(e.getGender()).phoneNumber(e.getPhoneNumber()).bloodGroup(e.getBloodGroup()).hospitalId(e.getHospital().getId()).build();} private void apply(Patient e,PatientDTO d){Hospital h=hr.findById(d.getHospitalId()).filter(BaseClass::getIsActive).orElseThrow(()->new ResourceNotFoundException("Hospital not found"));e.setName(d.getName());e.setGender(d.getGender());e.setPhoneNumber(d.getPhoneNumber());e.setBloodGroup(d.getBloodGroup());e.setHospital(h);} public PatientDTO create(PatientDTO d){Patient e=new Patient();apply(e,d);return dto(r.save(e));} public List<PatientDTO> all(){return r.findByIsActiveTrue().stream().map(this::dto).toList();} public PatientDTO get(Long id){return dto(find(id));} public PatientDTO update(Long id,PatientDTO d){Patient e=find(id);apply(e,d);return dto(r.save(e));} public void delete(Long id){Patient e=find(id);e.setIsActive(false);r.save(e);} public List<PatientDTO> admittedOnFloor(Integer floor){return r.admittedOnFloor(floor).stream().map(this::dto).toList();} public List<PatientDTO> outstanding(){return r.withOutstandingBills().stream().map(this::dto).toList();}}
